document.addEventListener('DOMContentLoaded',()=>{
document.querySelector('.topbar').hidden=true;document.querySelector('.sky')?.remove();const phone=document.querySelector('.phone');header=document.createElement('header');header.className='up-chrome';header.innerHTML=`<a class="up-brand" href="index.html"><img src="assets/logo.svg" alt="作业岛"></a><span class="up-header-points"></span><a class="up-mode-switch" href="${child?'parent':'child'}.html?v=20261019r" aria-label="切换到${child?'家长':'孩子'}端">${child?'家长端':'孩子端'} ↗</a>`;phone.prepend(header);
root=document.createElement('section');root.id='upgrade-root';root.className='view on up-main';root.dataset.view='upgrade';document.querySelector('.stage').prepend(root);
if(child)header.querySelector('.up-brand').innerHTML=hdIcon('house')+'<span>作业岛</span>';
if(ISLAND_PREVIEW){header.querySelector('.up-brand').href='child.html?preview=1';header.querySelector('.up-mode-switch').href=(child?'parent':'child')+'.html?preview=1';}
nav=document.createElement('nav');nav.className='up-nav';nav.setAttribute('aria-label','主要页面');document.querySelector('.tabbar').replaceWith(nav);ready=true;
const view=new URLSearchParams(location.search).get('view');if(view==='report'){ui.route=child?'island':'family';navigate('report');}else if(view==='settings')navigate('family');else if(view&&['shop','achieve','review','reward','classes'].includes(view)){ui.route=child?'island':'family';legacy(view);}else if(view==='calendar')navigate('plan');else if(view==='mates'){ui.route='island';navigate('mates');}else if(view==='publish'){navigate('today');openPublishSheet('manual');}else navigate('today');
});
